'use client'
import { useEffect, useRef } from 'react'
import { CURSOR_CSS, startCursor, type CursorMode } from '@/lib/effects/cursor'
import { whilePointerEffects } from '@/lib/effects/pointer'
import { cn } from '@/lib/cn'

// The site's pointer effects (effect/PointerEffects, CursorSwitch): one cursor effect for the whole page, drawn on a
// fixed canvas behind it. `trail` (the site's default) throws a dashed trail of the brand light with a few ASCII
// characters when the mouse flicks; `lens` reveals a soft circle of characters over empty page as the mouse moves;
// `burst` sends a small burst of light chips where a thrown mouse stops; `off` draws nothing. Each keeps clear of text,
// controls and pictures. Only for a fine pointer on a screen 768 wide or more, never with reduced motion or forced
// colours; it starts or stops as those change. Put one in the page's layout; pair it with the ASCII lens for the drifts. Decoration: hidden from assistive tech.
export interface CursorEffectsProps {
  /** trail, lens, burst or off. */
  mode?: CursorMode
  className?: string
}

export function CursorEffects({ mode = 'trail', className }: CursorEffectsProps) {
  const ref = useRef<HTMLCanvasElement>(null)
  useEffect(() => {
    const canvas = ref.current
    if (!canvas || mode === 'off') return
    return whilePointerEffects(() => startCursor(mode, canvas))
  }, [mode])
  return (
    <>
      <style href="ds-cursor-effects" precedence="ds">{CURSOR_CSS}</style>
      <canvas ref={ref} data-ds="cursor-effects" data-mode={mode} aria-hidden="true" className={cn('ds-cursor', className)} />
    </>
  )
}

export default CursorEffects

// The cursor effects' canvas (effect/Cursor*/cursor-*-effect.module.css), shared by both flavors: fixed behind the
// page, blended plus-lighter, shown only while drawing, for a fine pointer without reduced motion, never in forced
// colours.
export type CursorMode = 'trail' | 'lens' | 'burst' | 'off'

export const CURSOR_CSS = `
.ds-cursor { position: fixed; inset: 0; z-index: -1; display: none; width: 100%; height: 100%; pointer-events: none; user-select: none; mix-blend-mode: plus-lighter; }
@media (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference) { .ds-cursor[data-on] { display: block; } }
@media (forced-colors: active) { .ds-cursor[data-on] { display: none; } }
`

/** Starts the mode's effect on the canvas; resolves to its stop. */
export async function startCursor(mode: CursorMode, canvas: HTMLCanvasElement): Promise<() => void> {
	if (mode === 'trail') return (await import('@/lib/effects/cursor-trail')).mountTrail(canvas)
	if (mode === 'lens') return (await import('@/lib/effects/cursor-lens')).mountLens(canvas)
	if (mode === 'burst') return (await import('@/lib/effects/cursor-burst')).mountBurst(canvas)
	return () => {}
}

// The site's cursor trail (effect/CursorTrail): a quick flick of the mouse throws a dashed trail of the brand light
// (Blue, Green, Red, split like the lens) with a few ASCII characters along the path, fading in 320 to 560ms; it stays
// closed over text, controls and pictures. A fixed canvas behind the page (plus-lighter). The component starts it only
// for a fine pointer without reduced motion; forced colours hide it.
import { glyphInk, lightChannels } from "@/lib/effects/ink";
const GLYPH_RAMP = " .:-=+*#";
const GLYPH_SIZE = 13.333;
const CELL = { w: 8, h: 16 };
const GLYPH_BASELINE = 12;
const FALLBACK_FONT = "ui-monospace, SFMono-Regular, Menlo, monospace";

const MAX_DPR = 2;
const POOL = 16;
const GRID = 4;
const TELEPORT = 400;
const PATH_POINTS = 48;
const LENS_SPLIT = 0.5;

const SPEED_TAU = 24;
const FLICK_SPEED = 0.9;
const FLICK_FULL = 3.5;
const FLICK_RUN = 40;
const REARM = 0.5;
const DASH_GAP = 220;
const DASH_MIN = 6;
const DASH_MAX = 12;
const DASH_LEN = 176;
const DASH_LEAD = 32;
const SCATTER = 8;
const LIFE_MIN = 320;
const LIFE_MAX = 560;
const GLYPH_CHANCE = 0.35;
const GATE_FADE = 120;
const OPEN_HOLD = 120;
const TEXT_PAD = 24;
const IMAGE_PAD = 16;

const CLOSED =
  "p,h1,h2,h3,h4,h5,h6,li,dt,dd,a,button,input,textarea,select,label,img,picture,figure,blockquote,code,pre," +
  "[role=button],figcaption,summary,td,th,video,svg,[contenteditable],header,nav";
const IMAGES = "img,picture,figure,video,svg";
const HERO = 'section[aria-labelledby="hero-title"]';

type Sprite = { image: HTMLCanvasElement; w: number; h: number };
type Box = { l: number; t: number; r: number; b: number };

type Chip = {
  on: boolean;
  x: number;
  y: number;
  born: number;
  life: number;
  alpha: number;
  sprite: Sprite | null;
};

function chipSprite(size: number, dDevice: number, dpr: number): Sprite {
  const image = document.createElement("canvas");
  const side = Math.round(size * dpr);
  image.width = side + 2 * dDevice;
  image.height = side;
  const ctx = image.getContext("2d");
  if (ctx) {
    ctx.globalCompositeOperation = "lighter";
    for (const channel of lightChannels()) {
      ctx.fillStyle = channel.fill;
      ctx.fillRect(channel.step * dDevice, 0, side, side);
    }
  }
  return { image, w: image.width / dpr, h: image.height / dpr };
}

function glyphSprites(font: string, dpr: number): Sprite[] {
  return Array.from(GLYPH_RAMP, (char) => {
    const image = document.createElement("canvas");
    image.width = Math.round(CELL.w * dpr);
    image.height = Math.round(CELL.h * dpr);
    const ctx = image.getContext("2d");
    if (ctx) {
      ctx.scale(dpr, dpr);
      ctx.fillStyle = glyphInk();
      ctx.font = `${GLYPH_SIZE}px ${font}`;
      ctx.textAlign = "center";
      ctx.textBaseline = "alphabetic";
      ctx.fillText(char, CELL.w / 2, GLYPH_BASELINE);
    }
    return { image, w: CELL.w, h: CELL.h };
  });
}

const snap = (v: number, step: number) => Math.round(v / step) * step;
const clamp01 = (v: number) => Math.min(1, Math.max(0, v));
const inside = (box: Box, x: number, y: number) => x >= box.l && x <= box.r && y >= box.t && y <= box.b;

function isClosedTarget(target: EventTarget | null) {
  if (!(target instanceof Element)) return true;
  if (target.closest(CLOSED)) return true;
  for (const node of target.childNodes) {
    if (node.nodeType === Node.TEXT_NODE && node.textContent?.trim()) return true;
  }
  return false;
}

export function mountTrail(canvas: HTMLCanvasElement) {
  const ctx = canvas.getContext("2d");
  if (!ctx) return () => {};

  const finePointer = window.matchMedia("(hover: hover) and (pointer: fine)");
  const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)");

  const pool: Chip[] = Array.from({ length: POOL }, () => ({
    on: false,
    x: 0,
    y: 0,
    born: 0,
    life: 0,
    alpha: 0,
    sprite: null,
  }));
  let head = 0;
  let alive = 0;

  let dpr = 0;
  let sizeDirty = true;
  let font = FALLBACK_FONT;
  let fontAsked = false;
  const chips = new Map<string, Sprite>();
  let glyphs: Sprite[] = [];

  let hero: Element | null = null;
  let heroBox: Box | null = null;
  let zones: Box[] = [];
  let headerH = 0;
  let zonesDirty = true;
  let observer: ResizeObserver | null = null;

  const pathX = new Float64Array(PATH_POINTS);
  const pathY = new Float64Array(PATH_POINTS);
  let pathHead = 0;
  let pathCount = 0;

  let heroLookedAt = -Infinity;

  let raf = 0;
  let enabled = false;
  let tracking = false;
  let lastX = 0;
  let lastY = 0;
  let lastT = 0;
  let lastSX = 0;
  let lastSY = 0;
  let speed = 0;
  let run = 0;
  let armed = true;
  let lastDash = -Infinity;
  let lastTarget: EventTarget | null = null;
  let targetClosed = true;
  let closed = true;
  let closedAt = -Infinity;
  let openSince = Infinity;

  const chipFor = (size: number, intensity: number) => {
    const dDevice = Math.max(1, Math.round((size / 4) * (1 + LENS_SPLIT * intensity) * dpr));
    const key = `${size}:${dDevice}`;
    let sprite = chips.get(key);
    if (!sprite) {
      sprite = chipSprite(size, dDevice, dpr);
      chips.set(key, sprite);
    }
    return sprite;
  };

  const applySize = () => {
    sizeDirty = false;
    const next = Math.min(window.devicePixelRatio || 1, MAX_DPR);
    canvas.width = Math.round(document.documentElement.clientWidth * next);
    canvas.height = Math.round(document.documentElement.clientHeight * next);
    if (next !== dpr) {
      dpr = next;
      chips.clear();
      glyphs = glyphSprites(font, dpr);
    }
  };

  const markZones = () => {
    zonesDirty = true;
  };

  const measure = () => {
    zonesDirty = false;
    const sx = window.scrollX;
    const sy = window.scrollY;
    const box = (el: Element, pad: number): Box | null => {
      const r = el.getBoundingClientRect();
      if (r.width === 0 || r.height === 0) return null;
      return { l: r.left + sx - pad, t: r.top + sy - pad, r: r.right + sx + pad, b: r.bottom + sy + pad };
    };
    const found = document.querySelector(HERO);
    if (found !== hero) {
      observer?.disconnect();
      hero = found;
      if (hero && observer) {
        observer.observe(hero);
        const block = hero.querySelector("#hero-title")?.parentElement;
        if (block) observer.observe(block);
      }
    }
    heroBox = hero ? box(hero, 0) : null;
    zones = [];
    if (hero) {
      for (const el of hero.querySelectorAll(CLOSED)) {
        const b = box(el, el.matches(IMAGES) ? IMAGE_PAD : TEXT_PAD);
        if (b) zones.push(b);
      }
      const block = hero.querySelector("#hero-title")?.parentElement;
      if (block) {
        for (const el of block.children) {
          const b = box(el, TEXT_PAD);
          if (b) zones.push(b);
        }
      }
    }
    headerH = document.querySelector("header")?.getBoundingClientRect().height ?? 0;
  };

  const isOpen = (x: number, y: number) => {
    if (!heroBox || !inside(heroBox, x, y)) return false;
    if (y - window.scrollY < headerH) return false;
    for (const zone of zones) if (inside(zone, x, y)) return false;
    return true;
  };

  const askFont = () => {
    fontAsked = true;
    const family = getComputedStyle(canvas).getPropertyValue("--ds-font-ascii").trim();
    if (!family) return;
    document.fonts.load(`${GLYPH_SIZE}px ${family}`, GLYPH_RAMP).then(
      () => {
        if (!enabled) return;
        font = `${family}, ${FALLBACK_FONT}`;
        if (dpr) glyphs = glyphSprites(font, dpr);
      },
      () => {},
    );
  };

  const clearCanvas = () => {
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, canvas.width, canvas.height);
  };

  const tick = (now: number) => {
    raf = 0;
    if (sizeDirty) applySize();
    clearCanvas();
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.imageSmoothingEnabled = false;
    ctx.globalCompositeOperation = "lighter";

    const sx = window.scrollX;
    const sy = window.scrollY;
    ctx.save();
    if (heroBox) {
      const top = Math.max(heroBox.t - sy, headerH);
      ctx.beginPath();
      ctx.rect(heroBox.l - sx, top, heroBox.r - heroBox.l, Math.max(0, heroBox.b - sy - top));
      ctx.clip();
    }

    alive = 0;
    const gate = 1 - (now - closedAt) / GATE_FADE;
    for (const chip of pool) {
      if (!chip.on || !chip.sprite) continue;
      const t = Math.max(0, (now - chip.born) / chip.life);
      const cut = chip.born < closedAt ? gate : 1;
      if (t >= 1 || cut <= 0) {
        chip.on = false;
        continue;
      }
      alive++;
      const rest = 1 - t;
      ctx.globalAlpha = chip.alpha * rest * rest * Math.min(1, cut);
      const x = Math.round((chip.x - sx) * dpr) / dpr;
      const y = Math.round((chip.y - sy) * dpr) / dpr;
      ctx.drawImage(chip.sprite.image, x, y, chip.sprite.w, chip.sprite.h);
    }
    ctx.restore();

    if (alive) {
      raf = requestAnimationFrame(tick);
    } else {
      clearCanvas();
      delete canvas.dataset.on;
    }
  };

  const wake = () => {
    if (raf) return;
    canvas.dataset.on = "";
    raf = requestAnimationFrame(tick);
  };

  const take = () => {
    const chip = pool[head];
    head = (head + 1) % POOL;
    return chip;
  };

  const dash = (intensity: number, now: number) => {
    if (!fontAsked) askFont();
    if (sizeDirty) applySize();
    const count = Math.round(DASH_MIN + (DASH_MAX - DASH_MIN) * intensity);
    const targets = Array.from(
      { length: count },
      (_, i) => DASH_LEAD + ((i + Math.random()) / count) * DASH_LEN,
    );
    let next = 0;
    let travelled = 0;
    let tailX = 0;
    let tailY = 0;
    let tailNx = 0;
    let tailNy = 0;
    let placed = 0;
    for (let k = 1; k < pathCount && next < count; k++) {
      const ai = (pathHead - k + PATH_POINTS) % PATH_POINTS;
      const bi = (pathHead - k - 1 + PATH_POINTS) % PATH_POINTS;
      const ax = pathX[ai];
      const ay = pathY[ai];
      const dx = pathX[bi] - ax;
      const dy = pathY[bi] - ay;
      const seg = Math.hypot(dx, dy);
      if (seg === 0) continue;
      const ux = dx / seg;
      const uy = dy / seg;
      while (next < count && targets[next] <= travelled + seg) {
        const s = targets[next] - travelled;
        const f = 1 - (targets[next] - DASH_LEAD) / DASH_LEN;
        next++;
        const side = (Math.random() + Math.random() - 1) * SCATTER;
        const px = ax + ux * s - uy * side;
        const py = ay + uy * s + ux * side;
        if (!isOpen(px, py)) continue;
        const big = Math.random() < 0.2 + 0.3 * intensity;
        const size = big ? 8 : 4;
        const chip = take();
        chip.on = true;
        chip.born = now;
        chip.life = LIFE_MIN + (LIFE_MAX - LIFE_MIN) * f;
        chip.x = snap(px - size / 2, GRID);
        chip.y = snap(py - size / 2, GRID);
        chip.sprite = chipFor(size, intensity);
        chip.alpha = 1;
        tailX = px;
        tailY = py;
        tailNx = -uy;
        tailNy = ux;
        placed++;
      }
      travelled += seg;
    }
    if (!placed) return false;

    const rampIndex = Math.min(GLYPH_RAMP.length - 1, 1 + Math.floor(intensity * (GLYPH_RAMP.length - 1)));
    if (Math.random() < GLYPH_CHANCE && glyphs[rampIndex]) {
      const sign = Math.random() < 0.5 ? -1 : 1;
      const gx = tailX + tailNx * sign * 16;
      const gy = tailY + tailNy * sign * 16;
      if (isOpen(gx, gy)) {
        const chip = take();
        chip.on = true;
        chip.born = now;
        chip.life = LIFE_MIN;
        chip.x = snap(gx - CELL.w / 2, CELL.w);
        chip.y = snap(gy - CELL.h / 2, CELL.h);
        chip.sprite = glyphs[rampIndex];
        chip.alpha = 1;
      }
    }
    return true;
  };

  const close = (now: number) => {
    if (closed) return;
    closed = true;
    closedAt = now;
    if (alive && !raf) wake();
  };

  const onMove = (event: PointerEvent) => {
    if (event.pointerType !== "mouse" || document.hidden) return;
    const now = performance.now();
    if (hero && !hero.isConnected) zonesDirty = true;
    if (!hero && now - heroLookedAt > 500) {
      heroLookedAt = now;
      zonesDirty = true;
    }
    if (zonesDirty) measure();
    const sx = window.scrollX;
    const sy = window.scrollY;
    const cx = event.clientX;
    const cy = event.clientY;
    const x = cx + sx;
    const y = cy + sy;

    if (event.target !== lastTarget) {
      lastTarget = event.target;
      targetClosed = isClosedTarget(lastTarget);
    }
    if (targetClosed || !isOpen(x, y)) {
      close(now);
    } else if (closed) {
      closed = false;
      openSince = now;
    }

    if (!tracking || sx !== lastSX || sy !== lastSY) {
      tracking = true;
      lastX = cx;
      lastY = cy;
      lastT = event.timeStamp;
      lastSX = sx;
      lastSY = sy;
      speed = 0;
      run = 0;
      pathCount = 0;
    }
    const dx = cx - lastX;
    const dy = cy - lastY;
    const length = Math.hypot(dx, dy);
    const dt = Math.max(1, event.timeStamp - lastT);
    lastX = cx;
    lastY = cy;
    lastT = event.timeStamp;
    if (length > TELEPORT) {
      speed = 0;
      run = 0;
      pathCount = 0;
    }
    pathX[pathHead] = x;
    pathY[pathHead] = y;
    pathHead = (pathHead + 1) % PATH_POINTS;
    pathCount = Math.min(PATH_POINTS, pathCount + 1);
    if (length === 0 || length > TELEPORT) return;

    speed += (length / dt - speed) * (1 - Math.exp(-dt / SPEED_TAU));
    if (speed < FLICK_SPEED * REARM) armed = true;
    run = speed >= FLICK_SPEED ? run + length : 0;

    if (!armed || run < FLICK_RUN || closed || now - openSince < OPEN_HOLD || now - lastDash < DASH_GAP)
      return;
    armed = false;
    lastDash = now;
    if (dash(clamp01((speed - FLICK_SPEED) / (FLICK_FULL - FLICK_SPEED)), now)) wake();
  };

  const onGone = () => {
    tracking = false;
    close(performance.now());
  };

  const clearAll = () => {
    cancelAnimationFrame(raf);
    raf = 0;
    for (const chip of pool) chip.on = false;
    alive = 0;
    clearCanvas();
    delete canvas.dataset.on;
    tracking = false;
    closed = true;
    closedAt = performance.now();
  };

  const onResize = () => {
    sizeDirty = true;
    zonesDirty = true;
  };

  const onVisibility = () => {
    if (document.hidden) clearAll();
  };

  const listen = (on: boolean) => {
    const root = document.documentElement;
    if (on) {
      window.addEventListener("pointermove", onMove, { passive: true });
      window.addEventListener("resize", onResize);
      window.addEventListener("blur", onGone);
      root.addEventListener("pointerleave", onGone);
      document.addEventListener("visibilitychange", onVisibility);
      observer = new ResizeObserver(markZones);
      hero = null;
      zonesDirty = true;
    } else {
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("resize", onResize);
      window.removeEventListener("blur", onGone);
      root.removeEventListener("pointerleave", onGone);
      document.removeEventListener("visibilitychange", onVisibility);
      observer?.disconnect();
      observer = null;
      hero = null;
    }
  };

  const sync = () => {
    const next = finePointer.matches && !reduceMotion.matches;
    if (next === enabled) return;
    enabled = next;
    if (enabled) {
      applySize();
      listen(true);
    } else {
      listen(false);
      clearAll();
    }
  };

  sync();
  finePointer.addEventListener("change", sync);
  reduceMotion.addEventListener("change", sync);

  return () => {
    finePointer.removeEventListener("change", sync);
    reduceMotion.removeEventListener("change", sync);
    if (enabled) listen(false);
    enabled = false;
    clearAll();
  };
}

// The site's cursor lens (effect/CursorLens): moving the mouse over empty page reveals a soft circle of ASCII
// characters (112 to 152px, wider when faster) that fades when the pointer stops or reaches text, controls or pictures.
// A fixed canvas behind the page. Started only for a fine pointer without reduced motion.
import { glyphInk } from "@/lib/effects/ink";
const GLYPH_RAMP = " .:-=+*#";
const GLYPH_SIZE = 13.333;
const CELL_W = 8;
const CELL_H = 16;
const GLYPH_BASELINE = 12;
const FALLBACK_FONT = "ui-monospace, SFMono-Regular, Menlo, monospace";

const MAX_DPR = 2;
const MAX_CELLS = 1200;
const TELEPORT = 240;
const RECT_TTL = 200;
const SCAN_TTL = 4000;

const RADIUS_MIN = 112;
const RADIUS_MAX = 152;
const SPEED_TAU = 80;
const SPEED_STILL = 0.2;
const SPEED_FULL = 1.4;
const SPEED_CURVE = 1.5;
const STROKE_MIN = 96;
const TURN_MIN = 48;
const TURN_HOLD = 640;
const NEED_TURN = false;
const DENSITY_MIN = 0.6;
const FIELD_SCALE = 96;
const FIELD_FLOOR = 0.2;
const IDLE_MS = 64;
const RISE_MS = 80;
const STOP_FADE_MS = 640;
const CONTENT_FADE_MS = 120;
const CLEAR_HOLD_MS = 150;
const CELL_FADE_MS = 320;
const NEAR = 32;
const CLEAR_IN = 24;
const CLEAR_OUT = 72;

const CONTENT =
  "p,h1,h2,h3,h4,h5,h6,li,dt,dd,a,button,input,textarea,select,label,img,picture,figure,figcaption,blockquote,code,pre,summary,td,th,video,iframe,svg,[role=button],[role=img],[contenteditable],header";

type Cell = {
  key: number;
  i: number;
  j: number;
  g: number;
  a: number;
  pg: number;
  pa: number;
  seen: number;
};

type Sprite = { image: HTMLCanvasElement; w: number; h: number };

type Axis = { dir: number; start: number; peak: number };

function resetAxis(axis: Axis, p: number) {
  axis.dir = 0;
  axis.start = p;
  axis.peak = p;
}

function turned(axis: Axis, p: number) {
  if (axis.dir === 0) {
    if (Math.abs(p - axis.start) >= TURN_MIN) {
      axis.dir = Math.sign(p - axis.start);
      axis.peak = p;
    }
    return false;
  }
  if ((p - axis.peak) * axis.dir > 0) {
    axis.peak = p;
    return false;
  }
  if ((axis.peak - p) * axis.dir < TURN_MIN) return false;
  const stroke = Math.abs(axis.peak - axis.start);
  axis.start = axis.peak;
  axis.peak = p;
  axis.dir = -axis.dir;
  return stroke >= STROKE_MIN;
}

function glyphSprites(font: string, dpr: number): Sprite[] {
  return Array.from(GLYPH_RAMP, (char) => {
    const image = document.createElement("canvas");
    image.width = Math.round(CELL_W * dpr);
    image.height = Math.round(CELL_H * dpr);
    const ctx = image.getContext("2d");
    if (ctx) {
      ctx.scale(dpr, dpr);
      ctx.fillStyle = glyphInk();
      ctx.font = `${GLYPH_SIZE}px ${font}`;
      ctx.textAlign = "center";
      ctx.textBaseline = "alphabetic";
      ctx.fillText(char, CELL_W / 2, GLYPH_BASELINE);
    }
    return { image, w: CELL_W, h: CELL_H };
  });
}

const clamp01 = (v: number) => Math.min(1, Math.max(0, v));
const smoothstep = (a: number, b: number, v: number) => {
  const t = clamp01((v - a) / (b - a));
  return t * t * (3 - 2 * t);
};

function hash(x: number, y: number) {
  let h = (Math.imul(x, 374761393) + Math.imul(y, 668265263)) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

function valueNoise(x: number, y: number) {
  const xi = Math.floor(x);
  const yi = Math.floor(y);
  const fx = x - xi;
  const fy = y - yi;
  const ux = fx * fx * (3 - 2 * fx);
  const uy = fy * fy * (3 - 2 * fy);
  const a = hash(xi, yi);
  const b = hash(xi + 1, yi);
  const c = hash(xi, yi + 1);
  const d = hash(xi + 1, yi + 1);
  return a + (b - a) * ux + (c - a) * uy + (a - b - c + d) * ux * uy;
}

function texture(i: number, j: number) {
  const x = (i * CELL_W) / FIELD_SCALE;
  const y = (j * CELL_H) / FIELD_SCALE;
  const n = 0.65 * valueNoise(x, y) + 0.35 * valueNoise(x * 2.3 + 17, y * 2.3 + 31);
  return smoothstep(0.25, 0.75, n);
}

function hasOwnText(el: Element) {
  for (const node of el.childNodes) {
    if (node.nodeType === Node.TEXT_NODE && node.textContent?.trim()) return true;
  }
  return false;
}

function hasSurface(style: CSSStyleDeclaration) {
  if (style.backgroundImage && style.backgroundImage !== "none") return true;
  const color = style.backgroundColor;
  if (!color || color === "transparent") return false;
  if (color.startsWith("rgba(") && /,\s*0\)$/.test(color)) return false;
  if (/\/\s*0\)$/.test(color)) return false;
  return true;
}

function isContent(target: EventTarget | null) {
  if (!(target instanceof Element)) return false;
  if (target === document.documentElement || target === document.body) return false;
  if (target.closest(CONTENT) || hasOwnText(target)) return true;
  for (let el: Element | null = target; el && el !== document.body; el = el.parentElement) {
    if (hasSurface(getComputedStyle(el))) return true;
  }
  return false;
}

export function mountLens(canvas: HTMLCanvasElement) {
  const ctx = canvas.getContext("2d");
  if (!ctx) return () => {};

  const finePointer = window.matchMedia("(hover: hover) and (pointer: fine)");
  const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)");

  let dpr = 0;
  let sizeDirty = true;
  let headerBottom = 0;
  let font = FALLBACK_FONT;
  let fontAsked = false;
  let glyphs: Sprite[] = [];

  const cells = new Map<number, Cell>();
  const free: Cell[] = Array.from({ length: MAX_CELLS }, () => ({
    key: 0,
    i: 0,
    j: 0,
    g: 0,
    a: 0,
    pg: 0,
    pa: 0,
    seen: 0,
  }));
  let gen = 0;

  let candidates: Element[] = [];
  let scannedAt = -Infinity;
  let scanHandle = 0;
  let rectsAt = -Infinity;
  let rects = new Float64Array(0);
  let rectCount = 0;
  const local: number[] = [];

  let raf = 0;
  let lastTick = 0;
  let enabled = false;
  let tracking = false;
  let lastX = 0;
  let lastY = 0;
  let lastT = 0;
  let px = 0;
  let py = 0;
  let speed = 0;
  const axisX: Axis = { dir: 0, start: 0, peak: 0 };
  const axisY: Axis = { dir: 0, start: 0, peak: 0 };
  let turnAt = -Infinity;
  let level = 0;
  let lastMoveAt = -Infinity;
  let blockedAt = -Infinity;
  let overContent = false;
  let lastTarget: EventTarget | null = null;
  let dirty = false;
  let shown = 0;

  const applySize = () => {
    sizeDirty = false;
    const next = Math.min(window.devicePixelRatio || 1, MAX_DPR);
    canvas.width = Math.round(document.documentElement.clientWidth * next);
    canvas.height = Math.round(document.documentElement.clientHeight * next);
    headerBottom = parseFloat(getComputedStyle(document.documentElement).getPropertyValue(window.innerWidth < 1024 ? "--ds-header-bar-phone" : "--ds-size-header")) || 0;
    if (next !== dpr) {
      dpr = next;
      glyphs = glyphSprites(font, dpr);
    }
  };

  const askFont = () => {
    fontAsked = true;
    const family = getComputedStyle(canvas).getPropertyValue("--ds-font-ascii").trim();
    if (!family) return;
    document.fonts.load(`${GLYPH_SIZE}px ${family}`, GLYPH_RAMP).then(
      () => {
        if (!enabled) return;
        font = `${family}, ${FALLBACK_FONT}`;
        if (dpr) glyphs = glyphSprites(font, dpr);
      },
      () => {},
    );
  };

  const scan = () => {
    scanHandle = 0;
    scannedAt = performance.now();
    if (!fontAsked) askFont();
    const area = window.innerWidth * window.innerHeight;
    const found: Element[] = [];
    const taken = new Set<Element>();
    const all = document.body.getElementsByTagName("*");
    for (let k = 0; k < all.length; k++) {
      const el = all[k];
      if (el === canvas || el.tagName === "SCRIPT" || el.tagName === "STYLE") continue;
      if (el.parentElement && taken.has(el.parentElement)) {
        taken.add(el);
        continue;
      }
      if (el.matches(CONTENT) || hasOwnText(el)) {
        taken.add(el);
        found.push(el);
        continue;
      }
      if (el instanceof SVGElement) continue;
      const style = getComputedStyle(el);
      if (!hasSurface(style)) continue;
      const box = el.getBoundingClientRect();
      if (style.backgroundImage === "none" && box.width * box.height > area * 0.6) continue;
      taken.add(el);
      found.push(el);
    }
    candidates = found;
    rects = new Float64Array(found.length * 4);
    rectsAt = -Infinity;
  };

  const scheduleScan = () => {
    if (scanHandle) return;
    scanHandle =
      "requestIdleCallback" in globalThis
        ? globalThis.requestIdleCallback(scan, { timeout: 500 })
        : window.setTimeout(scan, 120);
  };

  const cancelScan = () => {
    if (!scanHandle) return;
    if ("cancelIdleCallback" in globalThis) globalThis.cancelIdleCallback(scanHandle);
    else window.clearTimeout(scanHandle);
    scanHandle = 0;
  };

  const measure = (now: number) => {
    rectsAt = now;
    const sx = window.scrollX;
    const sy = window.scrollY;
    rectCount = 0;
    for (const el of candidates) {
      if (!el.isConnected) continue;
      const box = el.getBoundingClientRect();
      if (box.width === 0 || box.height === 0) continue;
      const o = rectCount * 4;
      rects[o] = box.left + sx;
      rects[o + 1] = box.top + sy;
      rects[o + 2] = box.right + sx;
      rects[o + 3] = box.bottom + sy;
      rectCount++;
    }
  };

  const distToRect = (k: number, x: number, y: number) => {
    const o = k * 4;
    const dx = Math.max(rects[o] - x, 0, x - rects[o + 2]);
    const dy = Math.max(rects[o + 1] - y, 0, y - rects[o + 3]);
    return Math.hypot(dx, dy);
  };

  const retarget = (cell: Cell, g: number) => {
    if (cell.g === g) return;
    if (cell.g > 0 && cell.a >= cell.pa) {
      cell.pg = cell.g;
      cell.pa = cell.a;
    }
    cell.g = g;
    cell.a = 0;
  };

  const updateCells = (now: number) => {
    const sx = window.scrollX;
    const sy = window.scrollY;
    const cx = px + sx;
    const cy = py + sy;
    const radius = RADIUS_MIN + (RADIUS_MAX - RADIUS_MIN) * level;
    const gain = DENSITY_MIN + (1 - DENSITY_MIN) * level;

    if (now - rectsAt > RECT_TTL) measure(now);
    local.length = 0;
    const reach = radius + CLEAR_OUT;
    for (let k = 0; k < rectCount; k++) {
      const o = k * 4;
      if (rects[o + 2] < cx - reach || rects[o] > cx + reach) continue;
      if (rects[o + 3] < cy - reach || rects[o + 1] > cy + reach) continue;
      if (distToRect(k, cx, cy) < NEAR) {
        blockedAt = now;
        return false;
      }
      local.push(k);
    }

    gen++;
    const r2max = radius * radius;
    const top = sy + headerBottom;
    const i0 = Math.max(0, Math.floor((cx - radius) / CELL_W));
    const i1 = Math.floor((cx + radius) / CELL_W);
    const j0 = Math.max(0, Math.floor((cy - radius) / CELL_H));
    const j1 = Math.floor((cy + radius) / CELL_H);
    for (let j = j0; j <= j1; j++) {
      if (j * CELL_H < top) continue;
      const y = j * CELL_H + CELL_H / 2;
      for (let i = i0; i <= i1; i++) {
        const x = i * CELL_W + CELL_W / 2;
        const d2 = (x - cx) ** 2 + (y - cy) ** 2;
        if (d2 >= r2max) continue;
        let v = 1 - d2 / r2max;
        v *= v * gain * (FIELD_FLOOR + (1 - FIELD_FLOOR) * texture(i, j));
        if (v < 1 / GLYPH_RAMP.length) continue;
        for (const k of local) {
          const d = distToRect(k, x, y);
          if (d < CLEAR_OUT) v *= smoothstep(CLEAR_IN, CLEAR_OUT, d);
          if (v === 0) break;
        }
        const g = Math.min(GLYPH_RAMP.length - 1, Math.floor(v * GLYPH_RAMP.length));
        if (g < 1) continue;
        const key = j * 8192 + i;
        let cell = cells.get(key);
        if (!cell) {
          cell = free.pop();
          if (!cell) continue;
          cell.key = key;
          cell.i = i;
          cell.j = j;
          cell.g = 0;
          cell.a = 0;
          cell.pg = 0;
          cell.pa = 0;
          cells.set(key, cell);
        }
        cell.seen = gen;
        retarget(cell, g);
      }
    }
    for (const cell of cells.values()) {
      if (cell.seen !== gen) retarget(cell, 0);
    }
    return true;
  };

  const releaseAll = () => {
    for (const cell of cells.values()) free.push(cell);
    cells.clear();
  };

  const stop = () => {
    raf = 0;
    lastTick = 0;
    shown = 0;
    releaseAll();
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    delete canvas.dataset.on;
  };

  const tick = (now: number) => {
    raf = 0;
    const dt = lastTick ? Math.min(64, now - lastTick) : 16;
    lastTick = now;
    if (sizeDirty) applySize();

    let open = !overContent && now - blockedAt >= CLEAR_HOLD_MS;
    if (dirty) {
      dirty = false;
      if (open && level > 0) open = updateCells(now);
    }
    const target = open && now - lastMoveAt < IDLE_MS ? level : 0;
    const live = target > 0;
    if (target > shown) shown = Math.min(target, shown + dt / RISE_MS);
    else shown = Math.max(target, shown - dt / (open ? STOP_FADE_MS : CONTENT_FADE_MS));

    if (shown <= 0 && target <= 0) {
      stop();
      return;
    }

    const step = dt / CELL_FADE_MS;
    for (const cell of cells.values()) {
      if (cell.g > 0 && live) cell.a = Math.min(1, cell.a + step);
      if (cell.pa > 0) cell.pa = Math.max(0, cell.pa - step);
      if (cell.g === 0 && cell.pa === 0) {
        cells.delete(cell.key);
        free.push(cell);
      }
    }

    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.globalAlpha = 1;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.imageSmoothingEnabled = false;
    const sx = window.scrollX;
    const sy = window.scrollY;
    const w = canvas.width / dpr;
    const h = canvas.height / dpr;
    for (const cell of cells.values()) {
      const x = Math.round((cell.i * CELL_W - sx) * dpr) / dpr;
      const y = Math.round((cell.j * CELL_H - sy) * dpr) / dpr;
      if (y < headerBottom || y > h || x < -CELL_W || x > w) continue;
      if (cell.pa > 0) {
        const sprite = glyphs[cell.pg];
        ctx.globalAlpha = shown * cell.pa;
        ctx.drawImage(sprite.image, x, y, sprite.w, sprite.h);
      }
      if (cell.g > 0 && cell.a > 0) {
        const sprite = glyphs[cell.g];
        ctx.globalAlpha = shown * cell.a;
        ctx.drawImage(sprite.image, x, y, sprite.w, sprite.h);
      }
    }

    raf = requestAnimationFrame(tick);
  };

  const disarm = () => {
    resetAxis(axisX, px);
    resetAxis(axisY, py);
    turnAt = -Infinity;
    level = 0;
  };

  const wake = () => {
    if (raf) return;
    canvas.dataset.on = "";
    raf = requestAnimationFrame(tick);
  };

  const onMove = (event: PointerEvent) => {
    if (event.pointerType !== "mouse" || document.hidden) return;
    const now = performance.now();
    if (event.target !== lastTarget) {
      lastTarget = event.target;
      overContent = isContent(lastTarget);
    }
    if (overContent) blockedAt = now;
    px = event.clientX;
    py = event.clientY;
    if (!tracking) {
      tracking = true;
      lastX = px;
      lastY = py;
      lastT = event.timeStamp;
      speed = 0;
      disarm();
      return;
    }
    const length = Math.hypot(px - lastX, py - lastY);
    if (length === 0) return;
    const dt = Math.max(1, event.timeStamp - lastT);
    lastX = px;
    lastY = py;
    lastT = event.timeStamp;
    lastMoveAt = now;
    if (length > TELEPORT) {
      speed = 0;
      disarm();
      return;
    }
    speed += (length / dt - speed) * (1 - Math.exp(-dt / SPEED_TAU));
    const open = !overContent && now - blockedAt >= CLEAR_HOLD_MS;
    if (!open) {
      disarm();
    } else {
      const turnX = turned(axisX, px);
      const turnY = turned(axisY, py);
      if (turnX || turnY) turnAt = now;
      const u = clamp01((speed - SPEED_STILL) / (SPEED_FULL - SPEED_STILL));
      level = u > 0 && (!NEED_TURN || now - turnAt < TURN_HOLD) ? u ** SPEED_CURVE : 0;
    }
    if (level > 0) {
      if (!fontAsked) askFont();
      if (now - scannedAt > SCAN_TTL) scheduleScan();
      dirty = true;
      wake();
    } else if (shown > 0) {
      wake();
    }
  };

  const onScroll = () => {
    blockedAt = performance.now();
    lastTarget = null;
    disarm();
    if (shown > 0) wake();
  };

  const onGone = () => {
    tracking = false;
    lastTarget = null;
    blockedAt = performance.now();
    disarm();
    if (shown > 0) wake();
  };

  const clearAll = () => {
    cancelAnimationFrame(raf);
    stop();
    tracking = false;
    disarm();
  };

  const onResize = () => {
    sizeDirty = true;
    rectsAt = -Infinity;
    scannedAt = -Infinity;
  };

  const onVisibility = () => {
    if (document.hidden) clearAll();
  };

  const listen = (on: boolean) => {
    const root = document.documentElement;
    if (on) {
      window.addEventListener("pointermove", onMove, { passive: true });
      window.addEventListener("scroll", onScroll, { passive: true });
      window.addEventListener("resize", onResize);
      window.addEventListener("blur", onGone);
      root.addEventListener("pointerleave", onGone);
      document.addEventListener("visibilitychange", onVisibility);
    } else {
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onResize);
      window.removeEventListener("blur", onGone);
      root.removeEventListener("pointerleave", onGone);
      document.removeEventListener("visibilitychange", onVisibility);
    }
  };

  const sync = () => {
    const next = finePointer.matches && !reduceMotion.matches;
    if (next === enabled) return;
    enabled = next;
    if (enabled) {
      applySize();
      scheduleScan();
      listen(true);
    } else {
      listen(false);
      cancelScan();
      clearAll();
    }
  };

  sync();
  finePointer.addEventListener("change", sync);
  reduceMotion.addEventListener("change", sync);

  return () => {
    finePointer.removeEventListener("change", sync);
    reduceMotion.removeEventListener("change", sync);
    if (enabled) listen(false);
    enabled = false;
    cancelScan();
    clearAll();
  };
}

// The site's cursor burst (effect/CursorBurst): throwing the mouse and stopping sends out a small burst of light chips
// (Blue, Green, Red) and ASCII characters around the stop, fading in 640ms, never over text or pictures. A fixed canvas
// behind the page. Started only for a fine pointer without reduced motion.
import { glyphInk, lightChannels } from "@/lib/effects/ink";
const GLYPH_RAMP = " .:-=+*#";
const GLYPH_SIZE = 13.333;
const CELL = { w: 8, h: 16 };
const GLYPH_BASELINE = 12;
const FALLBACK_FONT = "ui-monospace, SFMono-Regular, Menlo, monospace";

const MAX_DPR = 2;
const POOL = 12;
const GRID = 4;
const TELEPORT = 240;
const LENS_SPLIT = 0.5;

const SPEED_WINDOW = 24;
const FAST_SPEED = 1.0;
const FULL_SPEED = 3;
const STILL_SPEED = 0.12;
const DECEL_WINDOW = 200;
const STOP_IDLE = 40;
const MIN_THROW = 64;
const BURST_GAP = 350;
const OPEN_DWELL = 120;
const CLEAR = 40;
const CHIPS_MIN = 6;
const CHIPS_MAX = 10;
const SPREAD = 12;
const TAIL = 12;
const GLYPH_CHANCE = 0.5;
const HOLD = 120;
const LIFE = 640;
const LIFE_EARLY = 120;
const CUT = 120;

const CONTENT =
  "p,h1,h2,h3,h4,h5,h6,li,dt,dd,a,button,input,textarea,select,label,img,picture,figure,figcaption,blockquote,code,pre,summary,td,th,video,canvas,svg,iframe,[role=button],[role=link],[role=tab],[role=switch],[role=slider],[role=checkbox],[role=radio],[contenteditable]";
const VISUALS = "img,picture,video,canvas,svg,iframe,figure";

type Sprite = { image: HTMLCanvasElement };

type Chip = {
  on: boolean;
  x: number;
  y: number;
  life: number;
  alpha: number;
  sprite: Sprite | null;
};

function chipSprite(side: number, dDevice: number): Sprite {
  const image = document.createElement("canvas");
  image.width = side + 2 * dDevice;
  image.height = side;
  const ctx = image.getContext("2d");
  if (ctx) {
    ctx.globalCompositeOperation = "lighter";
    for (const channel of lightChannels()) {
      ctx.fillStyle = channel.fill;
      ctx.fillRect(channel.step * dDevice, 0, side, side);
    }
  }
  return { image };
}

function glyphSprites(font: string, dpr: number): Sprite[] {
  return Array.from(GLYPH_RAMP, (char) => {
    const image = document.createElement("canvas");
    image.width = Math.round(CELL.w * dpr);
    image.height = Math.round(CELL.h * dpr);
    const ctx = image.getContext("2d");
    if (ctx) {
      ctx.scale(dpr, dpr);
      ctx.fillStyle = glyphInk();
      ctx.font = `${GLYPH_SIZE}px ${font}`;
      ctx.textAlign = "center";
      ctx.textBaseline = "alphabetic";
      ctx.fillText(char, CELL.w / 2, GLYPH_BASELINE);
    }
    return { image };
  });
}

const snap = (v: number, step: number) => Math.round(v / step) * step;
const clamp01 = (v: number) => Math.min(1, Math.max(0, v));

const surfaces = new WeakMap<Element, boolean>();
function isSurface(el: Element) {
  let known = surfaces.get(el);
  if (known === undefined) {
    const bg = getComputedStyle(el).backgroundColor;
    known = !(bg === "transparent" || /^rgba\(.*,\s*0\)$/.test(bg));
    surfaces.set(el, known);
  }
  return known;
}

const verdicts = new WeakMap<Element, boolean>();
function isContent(target: EventTarget | null): boolean {
  if (!(target instanceof Element)) return false;
  let verdict = verdicts.get(target);
  if (verdict === undefined) {
    verdict = target.closest(CONTENT) !== null;
    for (
      let el: Element | null = target;
      !verdict && el && el !== document.body && el !== document.documentElement;
    ) {
      verdict = isSurface(el);
      el = el.parentElement;
    }
    verdicts.set(target, verdict);
  }
  if (verdict) return true;
  for (const node of target.childNodes) {
    if (node.nodeType === Node.TEXT_NODE && node.textContent?.trim()) return true;
  }
  return false;
}

export function mountBurst(canvas: HTMLCanvasElement) {
  const ctx = canvas.getContext("2d");
  if (!ctx) return () => {};

  const finePointer = window.matchMedia("(hover: hover) and (pointer: fine)");
  const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)");

  const pool: Chip[] = Array.from({ length: POOL }, () => ({
    on: false,
    x: 0,
    y: 0,
    life: 0,
    alpha: 0,
    sprite: null,
  }));
  let born = 0;
  let cutAt = 0;

  let dpr = 0;
  let sizeDirty = true;
  let headerBottom = 0;
  let font = FALLBACK_FONT;
  let fontAsked = false;
  const chips = new Map<string, Sprite>();
  let glyphs: Sprite[] = [];

  let boxes: DOMRect[] = [];
  let boxesAt = -Infinity;
  let boxesScrollX = 0;
  let boxesScrollY = 0;
  let shiftX = 0;
  let shiftY = 0;

  let raf = 0;
  let stopTimer = 0;
  let enabled = false;

  const HISTORY = 32;
  let gap = 16;
  const hx = new Float64Array(HISTORY);
  const hy = new Float64Array(HISTORY);
  const ht = new Float64Array(HISTORY);
  let count = 0;
  let newest = -1;

  let armed = false;
  let fastAt = 0;
  let peak = 0;
  let thrown = 0;
  let dirX = 0;
  let dirY = 0;
  let contentAt = -Infinity;
  let lastBurst = -Infinity;

  const chipFor = (size: number, intensity: number) => {
    const side = Math.round(size * dpr);
    const dDevice = Math.max(1, Math.round((size / 4) * (1 + LENS_SPLIT * intensity) * dpr));
    const key = `${side}:${dDevice}`;
    let sprite = chips.get(key);
    if (!sprite) {
      sprite = chipSprite(side, dDevice);
      chips.set(key, sprite);
    }
    return sprite;
  };

  const applySize = () => {
    sizeDirty = false;
    const root = document.documentElement;
    const next = Math.min(window.devicePixelRatio || 1, MAX_DPR);
    canvas.width = Math.round(root.clientWidth * next);
    canvas.height = Math.round(root.clientHeight * next);
    headerBottom = parseFloat(getComputedStyle(root).getPropertyValue(window.innerWidth < 1024 ? "--ds-header-bar-phone" : "--ds-size-header")) || 0;
    if (next !== dpr) {
      dpr = next;
      chips.clear();
      glyphs = glyphSprites(font, dpr);
    }
  };

  const askFont = () => {
    fontAsked = true;
    const family = getComputedStyle(canvas).getPropertyValue("--ds-font-ascii").trim();
    if (!family) return;
    document.fonts.load(`${GLYPH_SIZE}px ${family}`, GLYPH_RAMP).then(
      () => {
        if (!enabled) return;
        font = `${family}, ${FALLBACK_FONT}`;
        if (dpr) glyphs = glyphSprites(font, dpr);
      },
      () => {},
    );
  };

  const pictureBoxes = (now: number) => {
    if (now - boxesAt > 400) {
      boxes = [];
      for (const el of document.querySelectorAll(VISUALS)) {
        if (el === canvas) continue;
        const r = el.getBoundingClientRect();
        if (r.width > 0 && r.height > 0) boxes.push(r);
      }
      boxesAt = now;
      boxesScrollX = window.scrollX;
      boxesScrollY = window.scrollY;
    }
    shiftX = boxesScrollX - window.scrollX;
    shiftY = boxesScrollY - window.scrollY;
  };

  const nearPicture = (x: number, y: number, margin: number, now: number) => {
    pictureBoxes(now);
    for (const r of boxes) {
      if (
        x > r.left + shiftX - margin &&
        x < r.right + shiftX + margin &&
        y > r.top + shiftY - margin &&
        y < r.bottom + shiftY + margin
      ) {
        return true;
      }
    }
    return false;
  };

  const ring = (n: number, r: number) =>
    Array.from({ length: n }, (_, i) => [
      Math.cos((i * 2 * Math.PI) / n) * r,
      Math.sin((i * 2 * Math.PI) / n) * r,
    ]);
  const RING = [[0, 0], ...ring(6, 0.3), ...ring(10, 0.65), ...ring(16, 1)];
  const isOpen = (x: number, y: number, now: number) => {
    const root = document.documentElement;
    if (
      x < CLEAR ||
      y < headerBottom + CLEAR ||
      x > root.clientWidth - CLEAR ||
      y > root.clientHeight - CLEAR
    ) {
      return false;
    }
    if (nearPicture(x, y, CLEAR, now)) return false;
    for (const [cx, cy] of RING) {
      if (isContent(document.elementFromPoint(x + cx * CLEAR, y + cy * CLEAR))) return false;
    }
    return true;
  };

  const tick = (now: number) => {
    raf = 0;
    if (sizeDirty) applySize();
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.globalCompositeOperation = "source-over";
    ctx.globalAlpha = 1;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.imageSmoothingEnabled = false;
    ctx.globalCompositeOperation = "lighter";

    const age = now - born;
    const cut = cutAt ? clamp01(1 - (now - cutAt) / CUT) : 1;
    let alive = 0;
    for (const chip of pool) {
      if (!chip.on || !chip.sprite) continue;
      if (age >= chip.life || cut <= 0) {
        chip.on = false;
        continue;
      }
      alive++;
      const rest = age <= HOLD ? 1 : 1 - (age - HOLD) / (chip.life - HOLD);
      ctx.globalAlpha = chip.alpha * rest * rest * cut;
      ctx.drawImage(chip.sprite.image, chip.x, chip.y);
    }

    if (alive) {
      raf = requestAnimationFrame(tick);
    } else {
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      delete canvas.dataset.on;
    }
  };

  const burst = (x: number, y: number, now: number) => {
    lastBurst = now;
    if (sizeDirty) applySize();
    const intensity = clamp01((peak - FAST_SPEED) / (FULL_SPEED - FAST_SPEED));
    const total = CHIPS_MIN + Math.round((CHIPS_MAX - CHIPS_MIN) * intensity);
    const taken = new Set<string>();
    let used = 0;

    const place = (cx: number, cy: number, size: number, alpha: number, life: number) => {
      const gx = snap(cx - size / 2, GRID);
      const gy = snap(cy - size / 2, GRID);
      const key = `${gx}:${gy}`;
      if (taken.has(key)) return false;
      taken.add(key);
      const chip = pool[used++];
      chip.on = true;
      chip.x = Math.round(gx * dpr);
      chip.y = Math.round(gy * dpr);
      chip.sprite = chipFor(size, intensity);
      chip.alpha = alpha;
      chip.life = life;
      return true;
    };

    place(x, y, 8, 1, LIFE);
    for (let tries = 0; used < total && tries < 40; tries++) {
      const across = (Math.random() + Math.random() - 1) * SPREAD;
      const along = (Math.random() + Math.random() - 1) * SPREAD * 0.5 - Math.random() * TAIL;
      const cx = x + dirX * along - dirY * across;
      const cy = y + dirY * along + dirX * across;
      const near = 1 - Math.min(1, Math.hypot(cx - x, cy - y) / (SPREAD + TAIL));
      const size = Math.random() < 0.15 + 0.25 * intensity ? 8 : 4;
      place(cx, cy, size, 0.55 + 0.4 * near, LIFE - LIFE_EARLY * (1 - near));
    }

    if (glyphs.length && used < POOL && Math.random() < GLYPH_CHANCE) {
      const ramp = Math.max(1, Math.min(GLYPH_RAMP.length - 1, Math.floor((0.3 + 0.7 * intensity) * 8)));
      const side = Math.random() < 0.5 ? -1 : 1;
      const gx = snap(x - CELL.w / 2 - dirY * side * (SPREAD + CELL.w), CELL.w);
      const gy = snap(y - CELL.h / 2 + dirX * side * (SPREAD + CELL.w), CELL.h);
      const chip = pool[used++];
      chip.on = true;
      chip.x = Math.round(gx * dpr);
      chip.y = Math.round(gy * dpr);
      chip.sprite = glyphs[ramp];
      chip.alpha = 1;
      chip.life = LIFE - LIFE_EARLY;
    }
    for (let i = used; i < POOL; i++) pool[i].on = false;

    born = performance.now();
    cutAt = 0;
    canvas.dataset.on = "";
    if (!raf) raf = requestAnimationFrame(tick);
  };

  const disarm = () => {
    armed = false;
    peak = 0;
    thrown = 0;
    if (stopTimer) {
      clearTimeout(stopTimer);
      stopTimer = 0;
    }
  };

  const stopped = (x: number, y: number, t: number) => {
    const ok = thrown >= MIN_THROW && t - lastBurst >= BURST_GAP && t - contentAt >= OPEN_DWELL;
    disarm();
    if (ok && isOpen(x, y, t)) burst(x, y, t);
  };

  const onStopTimer = () => {
    stopTimer = 0;
    if (!armed || newest < 0 || document.hidden) return;
    if (ht[newest] - fastAt <= DECEL_WINDOW) stopped(hx[newest], hy[newest], ht[newest]);
    else disarm();
  };

  const forget = () => {
    count = 0;
    newest = -1;
    disarm();
  };

  const cutBurst = () => {
    if (raf && !cutAt) cutAt = performance.now();
  };

  const onMove = (event: PointerEvent) => {
    if (event.pointerType !== "mouse" || document.hidden) return;
    const x = event.clientX;
    const y = event.clientY;
    const t = event.timeStamp;

    if (isContent(event.target) || nearPicture(x, y, GRID * 2, t)) {
      contentAt = t;
      cutBurst();
    }

    if (event.buttons !== 0) {
      forget();
      return;
    }

    if (newest >= 0) {
      const jump = Math.hypot(x - hx[newest], y - hy[newest]);
      if (jump > TELEPORT) forget();
      else if (jump === 0) return;
      else if (t - ht[newest] < 100) gap += (t - ht[newest] - gap) * 0.2;
    }
    newest = (newest + 1) % HISTORY;
    hx[newest] = x;
    hy[newest] = y;
    ht[newest] = t;
    count = Math.min(count + 1, HISTORY);
    if (count < 2) return;

    let back = (newest - 1 + HISTORY) % HISTORY;
    for (let k = 2; k < count && t - ht[back] < SPEED_WINDOW; k++) back = (back - 1 + HISTORY) % HISTORY;
    const prev = (newest - 1 + HISTORY) % HISTORY;
    const dx = x - hx[back];
    const dy = y - hy[back];
    const speed = Math.hypot(dx, dy) / Math.max(1, t - ht[back]);

    if (speed >= FAST_SPEED) {
      if (!armed && !fontAsked) askFont();
      armed = true;
      fastAt = t;
      peak = Math.max(peak, speed);
      const len = Math.hypot(dx, dy);
      dirX = dx / len;
      dirY = dy / len;
    }
    if (!armed) return;
    if (speed >= FAST_SPEED * 0.5) thrown += Math.hypot(x - hx[prev], y - hy[prev]);

    if (speed <= STILL_SPEED) {
      if (t - fastAt <= DECEL_WINDOW) stopped(x, y, t);
      else disarm();
      return;
    }
    if (speed < FAST_SPEED && t - fastAt > DECEL_WINDOW) {
      disarm();
      return;
    }
    if (stopTimer) clearTimeout(stopTimer);
    stopTimer = window.setTimeout(onStopTimer, Math.max(STOP_IDLE, gap * 2.5));
  };

  const clearAll = () => {
    cancelAnimationFrame(raf);
    raf = 0;
    for (const chip of pool) chip.on = false;
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    delete canvas.dataset.on;
    forget();
  };

  const onResize = () => {
    sizeDirty = true;
    boxesAt = -Infinity;
  };

  const onScroll = () => {
    cutBurst();
    disarm();
  };

  const onVisibility = () => {
    if (document.hidden) clearAll();
  };

  const listen = (on: boolean) => {
    const root = document.documentElement;
    if (on) {
      window.addEventListener("pointermove", onMove, { passive: true });
      window.addEventListener("resize", onResize);
      window.addEventListener("scroll", onScroll, { passive: true });
      window.addEventListener("blur", forget);
      root.addEventListener("pointerleave", forget);
      document.addEventListener("visibilitychange", onVisibility);
    } else {
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("resize", onResize);
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("blur", forget);
      root.removeEventListener("pointerleave", forget);
      document.removeEventListener("visibilitychange", onVisibility);
    }
  };

  const sync = () => {
    const next = finePointer.matches && !reduceMotion.matches;
    if (next === enabled) return;
    enabled = next;
    if (enabled) {
      applySize();
      listen(true);
    } else {
      listen(false);
      clearAll();
    }
  };

  sync();
  finePointer.addEventListener("change", sync);
  reduceMotion.addEventListener("change", sync);

  return () => {
    finePointer.removeEventListener("change", sync);
    reduceMotion.removeEventListener("change", sync);
    if (enabled) listen(false);
    enabled = false;
    clearAll();
  };
}

// The colours the canvas effects paint with, read from the brand tokens at draw time (a canvas cannot read var()):
// the light's Blue, Green and Red layers at their opacities, and the ASCII characters in the text colour at 0.35.
const read = (name: string) => (globalThis.document ? getComputedStyle(document.documentElement).getPropertyValue(name).trim() : '')

/** A token's colour with an alpha, as a canvas fill. */
export function ink(token: string, alpha: number): string {
	const v = read(token)
	const hex = /^#([0-9a-f]{6})$/i.exec(v)?.[1]
	if (hex) {
		const n = parseInt(hex, 16)
		return `rgb(${(n >> 16) & 255} ${(n >> 8) & 255} ${n & 255} / ${alpha})`
	}
	return v ? `color-mix(in srgb, ${v} ${alpha * 100}%, transparent)` : `rgb(255 255 255 / ${alpha})`
}

/** The light's three layers, Blue, Green and Red, at their opacities, with the step each is shifted by. */
export const lightChannels = () => [
	{ fill: ink('--ds-color-light-b', 0.782), step: 0 },
	{ fill: ink('--ds-color-light-g', 0.782), step: 1 },
	{ fill: ink('--ds-color-light-r', 0.85), step: 2 },
]

/** The ASCII characters: the text colour at the texture's 0.35. */
export const glyphInk = () => ink('--ds-color-fg', 0.35)

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}
